use std::{fs,collections::BTreeMap};fn main(){let root="research/hec_tensorprod631_20261116/timing";let s=fs::read_to_string(format!("{root}/cells.tsv")).unwrap();let(mut section_max,mut group_section_max)=(0f64,0f64);let mut count=0;for l in s.lines().skip(1){let a:Vec<_>=l.split('\t').collect();let total:u128=a[4].parse().unwrap();let text=fs::read_to_string(format!("{root}/{}-{}/work/reconstruct.stdout",a[0],a[1])).unwrap();let mut ns=BTreeMap::new();for l in text.lines().filter(|l|l.starts_with("TRACE_AGGREGATE ")){let f:BTreeMap<_,_>=l.split_whitespace().skip(1).filter_map(|s|s.split_once('=')).collect();ns.insert(f["name"],f["wall_ns"].parse::<u128>().unwrap());}let sec=ns["section_coords"];let sum=sec+ns["group_add_raw"]+ns["group_neg_raw"];assert!(sec<total&&sum<total);section_max=section_max.max(total as f64/(total-sec)as f64);group_section_max=group_section_max.max(total as f64/(total-sum)as f64);count+=1;}assert_eq!(count,20);println!("POSTHOC_BOUND cells={count} max_total_over_total_minus_sections={section_max:.12} max_generous_total_over_total_minus_group_plus_sections={group_section_max:.12} nested_group_overlap_doublecount_makes_bound_generous=true unchanged_measured_remainder_only=true not_generic_theorem=true");}
